ARENAS.each do |attributes|
  arena = Arena.find_or_initialize_by(slug: attributes.fetch(:slug))
  arena.assign_attributes(attributes)
  arena.save!
end

NFL_HOME_ARENAS_BY_SHORT_NAME.each do |short_name, arena_slug|
  Team.where(short_name: short_name, league: "nfl").update_all(home_arena_slug: arena_slug, updated_at: Time.current)
end

